import time, random, functools
from typing import Callable, Type

def retry_with_backoff(
    max_attempts: int = 3,
    base_delay: float = 1.0,
    max_delay: float = 60.0,
    exceptions: tuple[Type[Exception], ...] = (Exception,),
    jitter: bool = True,
):
    """Retry decorator with exponential backoff.

    Args:
        max_attempts: Total tries (including first).
        base_delay:   Initial wait seconds (doubles each retry).
        max_delay:    Hard cap on wait time.
        exceptions:   Exception types that trigger a retry.
        jitter:       Add ±50 % random jitter to avoid thundering herd.
    """
    def decorator(func: Callable) -> Callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            delay = base_delay
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == max_attempts:
                        raise
                    wait = min(delay, max_delay)
                    if jitter:
                        wait *= 0.5 + random.random()
                    print(f"Attempt {attempt} failed: {exc}. Retrying in {wait:.1f}s…")
                    time.sleep(wait)
                    delay *= 2
        return wrapper
    return decorator
